import{_ as n,a0 as u,w as s,s as a,ao as A,I as i,x as t,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"戴文的Linux内核专题：17 配置内核 (13) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux内核专题：17 配置内核 (13) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux内核专题：17 配置内核 (13) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux内核专题：17 配置内核 (13) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/17 The Linux Kernel--Configuring the Kernel Part 13","title":"戴文的Linux内核专题：17 配置内核 (13)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/17 The Linux Kernel--Configuring the Kernel Part 13.md","filePath":"[post].md"}'),l={name:"The Linux Kernel/17 The Linux Kernel--Configuring the Kernel Part 13.md"};function T(g,e,S,d,m,I){const p=u("Link");return s(),a("div",null,[e[11]||(e[11]=A('<h1 id="戴文的linux内核专题-17-配置内核-13" tabindex="-1">戴文的Linux内核专题：17 配置内核 (13) <a class="header-anchor" href="#戴文的linux内核专题-17-配置内核-13" aria-label="Permalink to “戴文的Linux内核专题：17 配置内核 (13)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.555/" alt=""></p><p>你好!这是Linux内核系列的下一篇，我们仍将配置ATA设备并将进入逻辑卷/存储。</p><p>&quot;ATA SFF support (for legacy IDE and PATA)&quot;应该启用，因为这扩展了ATA的能力。</p><p>为了支持Pacific Digital的ADMA控制器，应该启用&quot;Pacific Digital ADMA support&quot;。</p><p>&quot;Pacific Digital Serial ATA QStor support&quot;(串口ATA支持)在下一个驱动中支持</p><p>Promise的SATA SX4设备在内核中支持(Promise SATA SX4 support (Experimental))。</p><p>可以BMDMA的SFF ATA控制器需要这个驱动(ATA BMDMA support)。BMDMA代表总线主控直接内存访问(BMDMA stands for Bus-Master Direct Memory Access)。</p><p>下面，这个驱动对不同的SATA和PATA控制器提供支持Intel ESB, ICH, PIIX3, PIIX4 PATA/SATA support)。</p><p>这里有其他的特定设备驱动(Calxeda Highbank SATA support)、(Marvell SATA support)、(NVIDIA SATA support)、(Promise SATA TX2/TX4 support)、(Silicon Image SATA support)还有(SiS 964/965/966/180 SATA support)、(ServerWorks Frodo / Apple K2 SATA support)、(ULi Electronics SATA support)、(VIA SATA support)。。。由于有很多SATA/PATA控制器设计不同，一个通用驱动无法使用在这些设备上。</p><p>接下来，这个驱动支持PC卡上的ATA设备除非有特定设备管理硬件的驱动(PCMCIA PATA support)。</p><p>在这之后，有一个通用PATA驱动用于管理其他不被先前驱动支持的PATA设备 (Generic platform device PATA support)。</p><p>PATA设备的电源消耗由这个ACPI驱动管理(ACPI firmware driver for PATA)。强烈建议对系统上所有的硬件启用ACPI。虽然这会增加内核的大小，但是ACPI会增强性能。</p><p>&quot;Generic ATA support&quot;(通用ATA支持)由这个驱动提供。</p><p>古老的ISA、VLB和PCI总线PATA设备可以通过这个驱动支持(Legacy ISA PATA support (Experimental))。这个古老支持使用新的ATA层。</p><p>这组特性包含了许多对于RAID和LVM能力，可见下面的特性选项(Multiple devices driver support (RAID and LVM))。</p><p>有趣的事实：内核是由C和汇编写成的。</p><p>这个驱动允许RAID和LVM组合在一起。这用于使几个LVM卷使用RAID。分区被组合成逻辑块设备，然后形成RAID设备。</p><p>许多用户会希望RAID可以在启动时侦测到(Autodetect RAID arrays during kernel boot)。如果你没有RAID，那么不要启用这个特性。不然，启动处理会比原先希望的慢上几秒。</p><p>注意：当配置Linux内核时，最好按照&quot;use it or lose it&quot;(非用即失)的原则。那就是，如果你不用它，那就禁用这个特性。</p><p>硬盘分区可以通过这个驱动加在一起(Linear (append) mode)。</p><p>下面的驱动加入RAID-0支持带逻辑块设备中(RAID-0 (striping) mode)。接着还有 (RAID-1 (mirroring) mode)、(RAID-10 (mirrored striping) mode)和(RAID-4/RAID-5/RAID-6 mode)。</p><p>MD框架需要多路径支持(Multipath I/O support)。MD框架就是多设备(Multi Device)框架,它将多台设备作为一个单元管理。举例来说，将许多存储单元的分区组合起来可以使多个设备就像一个那样。多路径支持是用于使用处理虚拟的有多个地址的&quot;单个设备&quot;。因为单存储单元物理上有多件物理设备，所以它有多个硬件地址。</p><p>使用这个调试驱动，可以测试更大的多磁盘存储单元的bug(Faulty test module for MD)。</p><p>&quot;Device mapper support&quot;是一个用来映射逻辑扇区的卷管理器。LVM使用扇区映射。</p><p>如果启用的话，设备映射器可以有调试特性(Device mapper debugging support)。</p><p>如果需要，逻辑设备可以设置加密数据(Crypt target support)。这个特性允许用户将来加密那些存储设备。</p><p>只有启用了这个特性，才能使用逻辑存储单元的快照功能(Snapshot target)。</p><p>&quot;Thin provisioning&quot;(自动精简配置)允许逻辑卷设置成比组成逻辑卷的物理设备拥有更大的存储容量(Thin provisioning target)。这个特性同样为这类设备提供了快照功能。这额外的虚拟数据空间无法马上使用。这个特性的意义是允许用户在将来增加物理存储单元并且节约了配置逻辑块设备的时间。</p><p>用这个可以调试&quot;Thin provisioning&quot; (Keep stack trace of thin provisioning block lock holders)。</p><p>块设备性能的提升可以通过移动更多的常用数据到更快的存储单元中(Cache target (EXPERIMENTAL))。</p><p>卷管理器可以制成镜像逻辑卷(Mirror target)。</p><p>设备映射器(Device-mapper (dm))单元支持映射RAID1、RAID10、 RAID4、RAID5和RAID6(RAID 1/4/5/6/10 target)。</p><p>设备映射器(device-mapper)日志可以镜像到用户空间(Mirror userspace logging)。</p><p>&quot;Zero target&quot;是一个忽视写入并返回读取为零的设备。</p><p>接下来，卷管理器应该对硬件有多路径支持(Multipath target)。</p><p>这个驱动会发现最有效的到存储设备的路径来读取和写入(I/O Path Selector based on the number of in-flight I/Os)。</p><p>下面的一个驱动和以上相同，但是会寻找最快路径(I/O Path Selector based on the service time)。</p><p>如果一个逻辑卷上的物理存储单元正忙，如果可能的话，这个特性会允许读取/写入到另一个物理卷上。</p><p>udev可以生成设备管理器操作事件DM uevents)。udev是/dev的设备管理器。</p><p>为了测试软件/硬件对偶尔失败的输入/输出任务的逻辑设备如何反映，启用这个调试特性(Flakey target)。</p><p>逻辑卷可以创建为一个用于验证另一个逻辑分区数据的只读存储单元(Verity target support)。</p><p>注意：如果你喜欢我的文章，并且如果你有Linux.org的账号，请在我的文章上点击&quot;Like&quot;。同样，再次分享这篇文章在Google、Twitter和/或者Facebook上。</p><p>ConfigFS和TCM存储引擎可以通过这个设置启用(Generic Target Core Mod (TCM) and ConfigFS Infrastructure)。ConfigFS是一个基于内存的文件系统。</p><p>有趣的事实：Linux内核没有&quot;main()&quot;函数。在程序中，main()被依赖于kernel的libc调用。内核没有main()函数是因为libc将无法启动内核。如果内核的确有main()函数，那么我们就有一个&quot;鸡或者蛋&quot;的问题-谁先来？另外，内核的入口点用汇编写成，这并不使用main()函数。</p><p>下面，&quot;TCM/IBLOCK Subsystem Plugin for Linux/BLOCK&quot;可以禁用或者启用。</p><p>接着&quot;TCM/FILEIO Subsystem Plugin for Linux/VFS&quot;可以启用/禁用。</p><p>再次，还有两个TCM特性 - (TCM/pSCSI Subsystem Plugin for Linux/SCSI) 和 (TCM Virtual SAS target and Linux/SCSI LDD fabric loopback module)</p><p>对于ConfigFS的&quot;Linux-iSCSI.org iSCSI Target Mode Stack&quot;在这个驱动中支持(Linux-iSCSI.org iSCSI Target Mode Stack)。</p><p>下一步，可以启用/禁用&quot;FireWire SBP-2 fabric module&quot;。这允许一台计算机作为一个硬盘连接到另一台计算机上。</p><p>在这之后，我们可以配置&quot;Fusion Message Passing Technology (MPT) device support&quot;。</p><p>在那个标题下的第一个选项是一个用于并口适配器的SCSI支持的驱动(Fusion MPT ScsiHost drivers for SPI)。</p><p>SCSI同样也可以支持光纤通道主机适配器(Fusion MPT ScsiHost drivers for FC)和/或SAS适配器(Fusion MPT ScsiHost drivers for SAS)。</p><p>下一步，用户可以设置&quot;Maximum number of scatter gather entries&quot;。一个低的数值可以减少每个控制器实例的内存消耗。</p><p>下一个驱动提供了ioctl系统调用来管理MPT适配器(Fusion MPT misc device (ioctl) driver)。</p><p>光纤通道端口可以用这个驱动支持IP LAN的流量(Fusion MPT LAN driver)。</p><p>我可以读到你们的想法-你们会想到对于这个还有另外一篇文章。是的，你们想对了。请继续关注这个系列的下一篇文章。</p><p>如果你喜欢这个系列，请在Linux.org和/或者Google+上发表评论告诉我你有多喜欢这个系列，并且告诉我你想在今后的文章中希望看到的方面。或者给我发邮件DevynCJohnson@Gmail.com)。谢谢！</p><p>想要更多地了解作者，请检查下面的签名栏中的链接(译注：原文所在论坛有)</p><p>如果你已经完整地阅读了这篇文章，那么你应该已经看到单词&quot;Facebook&quot;三次了。如果没有，你没有阅读全部文章。</p><p>单词&quot;Facebook&quot;在这段中，上一段，和一个注解中。我打赌你阅读了上面的段落而没有通读文章来试图寻找第三个单词实例。</p><hr>',62)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),r(p,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-13.4714/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-13.4714/",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=t("译者：",-1)),r(p,{href:"https://github.com/geekpi"},{default:o(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),r(p,{href:"https://github.com/wxy"},{default:o(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),r(p,{href:"http://linux.cn/"},{default:o(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const x=n(l,[["render",T]]);export{P as __pageData,x as default};
